<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\CoreValue; use Illuminate\Http\Request;
class CoreValueController extends Controller { public function index(){return view('admin.core-values.index',['items'=>CoreValue::orderBy('sort_order')->paginate(20)]);} public function create(){return view('admin.core-values.form',['item'=>new CoreValue]);} public function store(Request $r){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');CoreValue::create($d);return redirect()->route('admin.core-values.index')->with('success','Core value created.');} public function edit(CoreValue $coreValue){return view('admin.core-values.form',['item'=>$coreValue]);} public function update(Request $r,CoreValue $coreValue){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');$coreValue->update($d);return redirect()->route('admin.core-values.index')->with('success','Core value updated.');} public function destroy(CoreValue $coreValue){$coreValue->delete();return back()->with('success','Core value deleted.');} private function data(Request $r){return $r->validate(['title'=>'required|string|max:150','description'=>'nullable|string|max:3000','sort_order'=>'nullable|integer|min:0','is_published'=>'nullable|boolean']);} }
